  "dk.sales.notes": { en: "Entries are manual; Brandlab can't read sales automatically. Show one income entry live, including the “where did the buyer come from” question, then the channel breakdown.", id: "Pencatatan masih manual; Brandlab belum bisa membaca penjualan otomatis. Tunjukkan satu Catat Pemasukan langsung, termasuk pertanyaan pembeli datang dari mana, lalu rincian channel-nya." },

  "dk.board.eyebrow": { en: "Step 7 · Board", id: "Langkah 7 · Board" },
  "dk.board.title": { en: "Brainstorm with your team", id: "Brainstorm bareng tim" },
  "dk.board.lead": { en: "Sketch ideas, flowcharts and meeting notes with your team, right next to your brand's data.", id: "Corat-coret ide, flowchart, dan catatan rapat bareng tim, langsung di samping data brand kamu." },
  "dk.board.result": { en: "Ideas, decisions and tasks in one place", id: "Ide, keputusan, dan tugas di satu tempat" },
  "dk.board.h1.t": { en: "Make a board", id: "Bikin papan" },
  "dk.board.h1.d": { en: "Start blank or from a template: brainstorm, mind map, content plan, creative brief and more.", id: "Mulai kosong atau dari template: brainstorming, mind map, rencana konten, creative brief, dan lainnya." },
  "dk.board.h2.t": { en: "Sketch freely", id: "Corat-coret" },
  "dk.board.h2.d": { en: "Sticky notes, text, shapes, arrows for flowcharts, a pen. Drop in images, PDFs or videos.", id: "Sticky note, teks, bentuk, garis panah untuk flowchart, pena. Tempel gambar, PDF, atau video." },
  "dk.board.h3.t": { en: "Bring people in", id: "Ajak orang" },
  "dk.board.h3.d": { en: "Tap Bagikan and send one link; whoever opens it joins without signing in.", id: "Klik Bagikan dan kirim satu link; yang membuka langsung masuk tanpa login." },
  "dk.board.h4.t": { en: "Meet & take notes", id: "Rapat & notulen" },
  "dk.board.h4.d": { en: "Run the timer, then “Selesai rapat & tulis notulen” saves who came, how long, decisions and tasks.", id: "Pakai timer, lalu Selesai rapat & tulis notulen menyimpan peserta, durasi, keputusan, dan tugas." },
  "dk.board.h5.t": { en: "Turn notes into action", id: "Jadikan aksi" },
  "dk.board.h5.d": { en: "Right-click a note to make it a task, send it to the content plan, or start a goal.", id: "Klik kanan catatan untuk jadikan tugas, kirim ke Rencana konten, atau jadikan campaign." },
  "dk.board.n1": { en: "Promo idea", id: "Ide promo" },
  "dk.board.n2": { en: "Customer Q&A", id: "Q&A pelanggan" },
  "dk.board.n3": { en: "Shoot Friday", id: "Syuting Jumat" },
  "dk.board.n4": { en: "Behind the scenes", id: "Behind the scene" },
  "dk.board.you": { en: "You", id: "Kamu" },
  "dk.board.team": { en: "Team", id: "Tim" },
  "dk.board.cta": { en: "Open Board", id: "Buka Board" },
  "dk.board.invite": { en: "Invite team", id: "Undang tim" },
  "dk.board.notes": { en: "For teams: one board for ideas, meetings and decisions, and every note can become a task or content.", id: "Untuk kerja tim: satu papan untuk ide, rapat, dan keputusan, dan tiap catatan bisa jadi tugas atau konten." },

  "dk.chat.eyebrow": { en: "Your sidekick · Tanya Brandlab", id: "Teman kerja · Tanya Brandlab" },
  "dk.chat.title": { en: "Stuck? Ask Brandlab.", id: "Buntu? Tanya Brandlab." },
  "dk.chat.lead": { en: "An AI chat that already knows your brand. It gives options and angles; you pick and edit.", id: "Chat AI yang sudah kenal brand kamu. Dia kasih pilihan dan sudut pandang, kamu yang milih dan nyunting." },
  "dk.chat.result": { en: "A sparring partner that knows your brand", id: "Teman diskusi yang kenal brand kamu" },
  "dk.chat.h1.t": { en: "Open it anywhere", id: "Buka dari mana saja" },
  "dk.chat.h1.d": { en: "The round button at the bottom right, on every page.", id: "Tombol bulat di pojok kanan bawah, di halaman mana pun." },
  "dk.chat.h2.t": { en: "Ask in your own words", id: "Tanya pakai bahasamu" },
  "dk.chat.h2.d": { en: "This week's ideas, a stronger hook, a caption, or what your numbers mean.", id: "Ide konten minggu ini, hook yang lebih kuat, caption, atau arti angka di report." },
  "dk.chat.h3.t": { en: "You choose", id: "Kamu yang milih" },
  "dk.chat.h3.d": { en: "It gives options and angles; pick one, edit it, or ask for another take.", id: "AI kasih pilihan dan sudut pandang; pilih satu, sunting, atau minta versi lain." },
  "dk.chat.h4.t": { en: "Make it content", id: "Jadikan konten" },
  "dk.chat.h4.d": { en: "An idea you like becomes content with one tap. Nothing is created until you tap.", id: "Ide yang cocok tinggal Jadikan konten. Nggak ada yang dibuat sebelum kamu tap." },
  "dk.chat.h5.t": { en: "Feed the Brand Memory", id: "Isi Memori Brand" },
  "dk.chat.h5.d": { en: "Tell it what happened (sales, customers, problems) and save it, so every AI answer uses the latest story.", id: "Ceritakan kejadian brand (penjualan, pelanggan, masalah) lalu simpan, supaya semua jawaban AI pakai cerita terbaru." },
  "dk.chat.m1": { en: "What should I post this week?", id: "Konten minggu ini enaknya apa ya?" },
  "dk.chat.m2": { en: "From your Brand DNA, three angles are worth a try. Which one fits you best?", id: "Dari Brand DNA kamu, ada 3 sudut yang bisa dicoba. Mana yang paling kamu banget?" },
  "dk.chat.cta": { en: "Open Tanya Brandlab", id: "Buka Tanya Brandlab" },
  "dk.chat.notes": { en: "Ask it something live from the room, about one of the founders' brands if someone volunteers. Show that it answers from the Brand DNA.", id: "Tanya langsung pertanyaan dari audiens, tentang brand salah satu founder kalau ada yang mau. Tunjukkan jawabannya berdasarkan Brand DNA." },

  "dk.loop.eyebrow": { en: "After that", id: "Setelah itu" },
  "dk.loop.title": { en: "Then it's a weekly routine.", id: "Tinggal rutin tiap minggu." },
  "dk.loop.lead": { en: "Plan, make, publish, fill in the numbers. Beranda always shows the one step to do today.", id: "Rencanakan, bikin, upload, isi angka. Beranda selalu kasih tahu satu langkah yang perlu dikerjakan hari ini." },
  "dk.loop.h1.t": { en: "Plan", id: "Rencanakan" },
  "dk.loop.h1.d": { en: "Start the week in Create's Calendar: fill this week, with AI if you like.", id: "Awal minggu buka Kalender di Create, isi minggu ini, boleh bareng AI." },
  "dk.loop.h2.t": { en: "Make", id: "Bikin" },
  "dk.loop.h2.d": { en: "Work each post stage by stage; Beranda shows what's due today.", id: "Kerjakan konten tahap demi tahap; Beranda menunjukkan yang perlu dikerjakan hari ini." },
  "dk.loop.h3.t": { en: "Publish", id: "Upload" },
  "dk.loop.h3.d": { en: "Post it, then mark it Sudah tayang so your goal moves.", id: "Posting, lalu tandai Sudah tayang supaya progres tujuan ikut jalan." },
  "dk.loop.h4.t": { en: "Fill in numbers", id: "Isi angka" },
  "dk.loop.h4.d": { en: "A few days after posting, add the numbers; Report and your goal update.", id: "Beberapa hari setelah tayang, isi angkanya; Report dan tujuan ikut ter-update." },
  "dk.loop.l1": { en: "Plan", id: "Rencanakan" },
  "dk.loop.l2": { en: "Make", id: "Bikin" },
  "dk.loop.l3": { en: "Publish", id: "Upload" },
  "dk.loop.l4": { en: "Numbers", id: "Isi angka" },
  "dk.loop.center": { en: "Every week", id: "Tiap minggu" },
